# region: render
def render(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: emit
def emit(xs):
    return [v for v in xs if v % 2 == 0]

# region: gather
def gather(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs, offset=-1):
    return [v + offset for v in xs]

# region: digest
def digest(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs) - 1, 'tally': sorted(d.items())}

# region: intake
def intake(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return intake(digest(sift(gather(emit(render(raw))))))

